"use client"

import * as React from "react"
import { GlimmProvider, useGlimm } from "glimm/react"

const rows = [
  ["Northwind Labs", "EMEA", "Sara Lind", "$184,000", "Negotiation", "Nov 14"],
  ["Halcyon Health", "NA", "Marcus Ode", "$162,500", "Proposal", "Dec 02"],
  ["Brightline Freight", "NA", "Priya Shah", "$148,000", "Won", "Oct 28"],
  ["Kestrel Bank", "APAC", "Jun Park", "$131,200", "Negotiation", "Nov 21"],
  ["Morrow & Finch", "EMEA", "Sara Lind", "$118,750", "Discovery", "Dec 19"],
  ["Atlas Robotics", "NA", "Leo Brandt", "$104,000", "Proposal", "Dec 05"],
  ["Tidewater Energy", "LATAM", "Ana Costa", "$97,400", "Negotiation", "Nov 30"],
  ["Pinecrest Schools", "NA", "Marcus Ode", "$88,000", "Won", "Oct 24"],
  ["Solace Insurance", "EMEA", "Tom Becker", "$83,600", "Proposal", "Dec 11"],
  ["Vela Mobility", "APAC", "Jun Park", "$76,900", "Discovery", "Dec 23"],
  ["Corvid Security", "NA", "Priya Shah", "$71,250", "Negotiation", "Nov 18"],
  ["Larkspur Foods", "LATAM", "Ana Costa", "$64,000", "Proposal", "Dec 09"],
] as const

const columns = ["Account", "Region", "Owner", "Deal size", "Stage", "Close date"]
const widths = ["24%", "14%", "18%", "16%", "15%", "13%"]

function Skeleton({ width, height = 8 }: { width: string | number; height?: number }) {
  return <span aria-hidden="true" style={{ background: "#f0f0f1", borderRadius: 6, display: "block", height, width }} />
}

function SheetToolbar() {
  return (
    <>
      <header style={{ alignItems: "center", borderBottom: "1px solid #ececee", display: "flex", height: 44, justifyContent: "space-between", padding: "0 16px" }}>
        <div style={{ alignItems: "center", display: "flex", gap: 12 }}><Skeleton height={24} width={24} /><Skeleton height={10} width={110} /></div>
        <div style={{ alignItems: "center", display: "flex", gap: 12 }}><Skeleton height={30} width={30} /><Skeleton height={32} width={72} /></div>
      </header>
      <div style={{ alignItems: "center", borderBottom: "1px solid #ececee", display: "flex", gap: 8, height: 40, overflow: "hidden", padding: "0 12px" }}>
        {[24, 24, 24, 56, 24, 24, 24, 56, 24, 24].map((width, index) => <Skeleton height={24} key={index} width={width} />)}
      </div>
      <div style={{ alignItems: "center", borderBottom: "1px solid #ececee", display: "flex", gap: 14, height: 32, padding: "0 12px" }}><Skeleton width={28} /><Skeleton width={14} /><Skeleton width={120} /></div>
    </>
  )
}

function SheetGrid({ generated }: { generated: boolean }) {
  return (
    <div style={{ bottom: 0, left: 0, overflow: "hidden", position: "absolute", right: 0, top: 116 }}>
      <div style={{ background: "#fafafa", borderBottom: "1px solid #ececee", display: "grid", gridTemplateColumns: "44px repeat(6, 1fr)", height: 26 }}>
        <span style={{ borderRight: "1px solid #ececee" }} />
        {columns.map((_, index) => <span key={index} style={{ alignItems: "center", borderRight: "1px solid #ececee", display: "flex", justifyContent: "center" }}><Skeleton height={7} width={8} /></span>)}
      </div>
      {generated ? (
        <div style={{ fontFamily: "Inter, ui-sans-serif, system-ui, sans-serif", fontSize: 13, fontVariantNumeric: "tabular-nums" }}>
          <div style={{ display: "grid", gridTemplateColumns: `44px ${widths.join(" ")}`, height: 30 }}>
            <span style={{ alignItems: "center", background: "#fafafa", borderBottom: "1px solid #ececee", borderRight: "1px solid #ececee", color: "#b5b5b8", display: "flex", justifyContent: "center" }}>1</span>
            {columns.map((column) => <span key={column} style={{ alignItems: "center", borderBottom: "1px solid #ececee", borderRight: "1px solid #ececee", color: "#98989d", display: "flex", padding: "0 12px" }}>{column}</span>)}
          </div>
          {rows.map((row, rowIndex) => (
            <div key={row[0]} style={{ display: "grid", gridTemplateColumns: `44px ${widths.join(" ")}`, height: 30 }}>
              <span style={{ alignItems: "center", background: "#fafafa", borderBottom: "1px solid #ececee", borderRight: "1px solid #ececee", color: "#c4c4c7", display: "flex", justifyContent: "center" }}>{rowIndex + 2}</span>
              {row.map((cell, index) => (
                <span key={index} style={{ alignItems: "center", borderBottom: "1px solid #ececee", borderRight: "1px solid #ececee", color: "#292a2e", display: "flex", justifyContent: index === 3 || index === 5 ? "flex-end" : "flex-start", minWidth: 0, overflow: "hidden", padding: "0 12px", whiteSpace: "nowrap" }}>
                  {index === 4 ? <span style={{ background: cell === "Won" ? "#ebfaee" : cell === "Proposal" ? "#fff7e8" : cell === "Negotiation" ? "#edf5ff" : "#f1f1f2", borderRadius: 4, color: cell === "Won" ? "#48a65d" : cell === "Proposal" ? "#ce9638" : cell === "Negotiation" ? "#4f8cca" : "#68686d", padding: "1px 5px" }}>{cell}</span> : cell}
                </span>
              ))}
            </div>
          ))}
        </div>
      ) : (
        Array.from({ length: 15 }, (_, rowIndex) => (
          <div key={rowIndex} style={{ display: "grid", gridTemplateColumns: "44px repeat(6, 1fr)", height: 30 }}>
            <span style={{ alignItems: "center", background: "#fafafa", borderBottom: "1px solid #ececee", borderRight: "1px solid #ececee", display: "flex", justifyContent: "center" }}><Skeleton height={7} width={7} /></span>
            {Array.from({ length: 6 }, (_, index) => <span key={index} style={{ alignItems: "center", borderBottom: "1px solid #ececee", borderRight: "1px solid #ececee", display: "flex", justifyContent: index === 3 || index === 5 ? "flex-end" : "flex-start", padding: "0 12px" }}><Skeleton width={`${35 + ((rowIndex * 13 + index * 17) % 36)}%`} /></span>)}
          </div>
        ))
      )}
    </div>
  )
}

function GeneratePanel() {
  const [generated, setGenerated] = React.useState(false)
  const [working, setWorking] = React.useState(false)
  const { sweep } = useGlimm()

  const run = React.useCallback(() => {
    if (working) return
    if (generated) {
      setGenerated(false)
      return
    }
    setWorking(true)
    window.setTimeout(() => {
      sweep(() => {
        setGenerated(true)
        setWorking(false)
      }, { palette: "prism", direction: "ltr", sweepMs: 1050, outroMs: 180 })
    }, 180)
  }, [generated, sweep, working])

  return (
    <main style={{ background: "#fff", color: "#242529", fontFamily: "Inter, ui-sans-serif, system-ui, sans-serif", minHeight: "100vh", overflow: "hidden", position: "relative", width: "100%" }}>
      <SheetToolbar />
      <SheetGrid generated={generated} />
      <section style={{ bottom: 22, left: "50%", maxWidth: 600, position: "absolute", transform: "translateX(-50%)", width: "calc(100% - 32px)", zIndex: 5 }}>
        <div style={{ background: "rgba(255,255,255,.96)", borderRadius: 16, boxShadow: "0 12px 35px rgba(0,0,0,.10), 0 0 0 1px rgba(0,0,0,.06)", padding: 12 }}>
          <div style={{ color: "#242529", fontSize: 13, fontWeight: 450, letterSpacing: "-0.08px", lineHeight: "18px", minHeight: 42 }}>Fill this sheet with our top 12 open deals for Q4: account, region, owner, deal size, stage and expected close date.</div>
          <div style={{ alignItems: "center", display: "flex", justifyContent: "space-between", marginTop: 4 }}>
            <button aria-label="Add" type="button" style={{ alignItems: "center", background: "#fafafa", border: 0, borderRadius: 999, color: "#9a9a9e", display: "inline-flex", fontSize: 22, height: 36, justifyContent: "center", width: 36 }}>+</button>
            <button aria-label={generated ? "Clear" : working ? "Stop" : "Generate"} onClick={run} type="button" style={{ alignItems: "center", background: generated ? "#fff" : "#242529", border: generated ? "1px solid #e6e6e8" : 0, borderRadius: 999, boxShadow: generated ? "0 1px 2px rgba(0,0,0,.04)" : "none", color: generated ? "#35363a" : "#fff", cursor: "pointer", display: "inline-flex", fontFamily: "inherit", fontSize: 13, fontWeight: 450, height: 36, justifyContent: "center", minWidth: 74, padding: "0 16px" }}>{generated ? "Clear" : working ? "Stop" : "Generate"}</button>
          </div>
        </div>
      </section>
    </main>
  )
}

function GlimmGenerateData() {
  return <GlimmProvider><GeneratePanel /></GlimmProvider>
}

export { GlimmGenerateData }
export default GlimmGenerateData

